--region init
function ParkourBossDetailDamageBonusDialog:AddUIClick()
    SetButtonAction(self.BtnClose, Bind(self, self.OnBtnCloseHandler))
    SetButtonAction(self.Fuzzy, Bind(self, self.OnBtnCloseHandler))
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnOneKeyDrawHandler))
end

function ParkourBossDetailDamageBonusDialog:InitData()
    if isNull(self._damageRewardList) then
        self._damageRewardList = CfUtils.GetCf(AutoIds.IdSetting6453, "ActivityCakeBossHurtVo", true)
    end
    self._historyMaxHurt = checkNumber(self.data.playerRank.damage)
    self._isCanOneKeyDraw = self:IsCanOneKeyDrawReward()
    self:RefreshUI()
end
--endregion init

--region handler
function ParkourBossDetailDamageBonusDialog:OnBtnOneKeyDrawHandler()
    if not self._isCanOneKeyDraw then
        return
    end
    self:DrawReward(0)
end

function ParkourBossDetailDamageBonusDialog:OnDrawDamageRewardHandler()
    self:InitData()
end

function ParkourBossDetailDamageBonusDialog:OnBtnCloseHandler()
    UIModule.CloseDialog(self.controller)
end
--endregion handler

--region private
function ParkourBossDetailDamageBonusDialog:InitItemByIndex(listView, index)
    local luaIndex = index + 1
    local cellData = self._damageRewardList[luaIndex]
    local cell = listView:NewListViewItem("Cell")
    ---@type ActivityCakeShopBossDamageBonusCell
    local scr = CfUtils.GetLuaScr(cell, "Game.Activity.ParkourGame.Dialog.ParkourBossDamageBonusCell")
    scr:SetCallBack(function(id) self:OnDrawRewardClick(id)  end)
    local idHaveDraw = self:IsHaveDrawBossHurtReward(cellData.id)
    scr:Refresh(cellData, self._historyMaxHurt, idHaveDraw)
    return cell
end

function ParkourBossDetailDamageBonusDialog:OnDrawRewardClick(id)
    local idHaveDraw = self:IsHaveDrawBossHurtReward(id)
    if idHaveDraw then
        GameUtils.Toast(localize("奖励已经领取"))
        return
    end
    self:DrawReward(id)
end

function ParkourBossDetailDamageBonusDialog:DrawReward(id)
    GameUtils.Request("activityTinyWorld/receiveBossDamageRewards", {activityUuid = self.activityUuid,rewardId = id} , function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        local rewards = jsonData.rewards
        self:UpdateReward(id)
        if #rewards > 0 then
            GoodsUtils.DrawRewards(rewards)
            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
        end
        self:OnDrawDamageRewardHandler()
        Events.Broadcast("BOSS_DMG_REWARD", id)
    end)
end

function ParkourBossDetailDamageBonusDialog:UpdateReward(rewardId)
    if checkNumber(rewardId) == 0 then
        -- 1. 获取所有奖励
        local allRewards = CfUtils.GetCf(AutoIds.IdSetting6453, "ActivityCakeBossHurtVo", true)
        -- 2. 获取所有可领取但未领取的奖励
        local allCanDrawButNotInListRewards = {}
        local historyMaxHurt = checkNumber(self.data.playerRank.damage)
        for i, reward in ipairs(allRewards) do
            ---@type MidFestivalBossDamageRewardVo
            local rewardVo = reward
            if checkNumber(historyMaxHurt) >= checkNumber(rewardVo.upperLimit) and (not table.isContain(self.data.receivedDamageRewardIds, rewardVo.id, function(id, cId) return checkNumber(id) == checkNumber(cId)  end)) then
                table.insert(allCanDrawButNotInListRewards, rewardVo)
            end
        end
        -- 3. 将他们全部设置为已领取
        for _, rewardVo in ipairs(allCanDrawButNotInListRewards) do
            table.insert(self.data.receivedDamageRewardIds,rewardVo.id)
        end
    else
        if not table.isContain(self.data.receivedDamageRewardIds, rewardId, function(id, cId) return checkNumber(id) == checkNumber(cId)  end) then
            table.insert(self.data.receivedDamageRewardIds, rewardId)
        end
    end
end

function ParkourBossDetailDamageBonusDialog:RefreshUI()
    CfUtils.SetActive(self.FontStyleButton, self._isCanOneKeyDraw)

    if not self.DamageLoopView.IsListViewInit then
        self.DamageLoopView:InitListView(#self._damageRewardList, Bind(self, self.InitItemByIndex))
    else
        GameUtils.ReloadData(self.DamageLoopView, #self._damageRewardList)
    end
end
--endregion private

function ParkourBossDetailDamageBonusDialog:IsHaveDrawBossHurtReward(id)
    for i, v in pairs(self.data.receivedDamageRewardIds) do
        if checkNumber(v) == id then
            return true
        end
    end
    return false
end
--region public
function ParkourBossDetailDamageBonusDialog:IsCanOneKeyDrawReward()
    -- 获取所有奖励
    local allRewards = self._damageRewardList
    -- 获取所有可领取的奖励
    local historyMaxHurt = self._historyMaxHurt
    local allCanDrawButNotInListRewards = {}
    for _, reward in ipairs(allRewards) do
        ---@type MidFestivalBossDamageRewardVo
        local rewardVo = reward
        if historyMaxHurt >= checkNumber(rewardVo.upperLimit) and (not self:IsHaveDrawBossHurtReward(rewardVo.id)) then
            table.insert(allCanDrawButNotInListRewards, rewardVo)
        end
    end
    return table.count(allCanDrawButNotInListRewards) > 0
end
--endregion public

